    if arg.startswith("-") and arg != "-":
        # Only the separated form ("-X PUT") consumes the next argv. Combined
        # forms such as -XPUT are left intact for curl to interpret.
        return len(arg) == 2 and arg[1] in req_short
    return False


def is_curlie_method(s: str) -> bool:
    return s.upper() in METHODS


def split_args(argv: List[str]) -> Tuple[bool, bool, bool, List[str], List[str]]:
    curl_mode = False
    pretty = False
    form = False
    curl_opts: List[str] = []
    pos: List[str] = []
    req_long, req_short = parse_curl_option_specs()
    i = 0
    after_dd = False
    while i < len(argv):
        a = argv[i]
        if after_dd:
            pos.append(a); i += 1; continue
        if a == "--":
            curl_opts.append(a); after_dd = True; i += 1; continue
        if a == "--curl":
            curl_mode = True; i += 1; continue
        if a == "--pretty":
            pretty = True; i += 1; continue
        if a == "--form":
            form = True; i += 1; continue
        if a.startswith("-") and a != "-":
            curl_opts.append(a)
            if option_consumes(a, req_long, req_short) and i + 1 < len(argv):
                curl_opts.append(argv[i+1])
                i += 2
            else:
                i += 1
            continue
        pos.append(a)
        i += 1
    return curl_mode, pretty, form, curl_opts, pos


def classify_positionals(pos: List[str]) -> Tuple[str, str, List[str], List[str]]:
    """Return method, url, request_items, extra plain args."""
    method = ""
    if len(pos) >= 2 and is_curlie_method(pos[0]):
        method = pos[0].upper()
        url = pos[1]
        rest = pos[2:]
    elif pos:
        url = pos[0]
        rest = pos[1:]
    else:
        return "", "", [], []
    items: List[str] = []
    extras: List[str] = []
    for r in rest:
        if (":=" in r) or ("==" in r) or ("=" in r) or (":" in r):
            items.append(r)
        else:
            extras.append(r)
    return method, url, items, extras


def json_raw_value(s: str) -> Any:
    try:
        return json.loads(s)
    except Exception:
        return None


def parse_items(items: List[str], form: bool) -> Tuple[List[str], Dict[str, Any], List[Tuple[str, str]], List[str], bool, bool]:
    """Return item curl opts, json object, query pairs, raw extras, has_accept, has_content_type."""
    curl_item_opts: List[str] = []
    data: Dict[str, Any] = {}
    query: List[Tuple[str, str]] = []
    raw_extras: List[str] = []
    has_accept = False
    has_content_type = False
    for it in items:
        if ":=" in it:
            k, v = it.split(":=", 1)
            data[k] = json_raw_value(v)
        elif "==" in it:
            k, v = it.split("==", 1)
            query.append((k, v))
        elif ":" in it and "=" not in it.split(":", 1)[0]:
            # Header syntax. This deliberately treats ':value' as a header,
            # matching curlie's permissive parser.
            curl_item_opts.extend(["-H", it])
            name = it.split(":", 1)[0].strip().lower()
            if name == "accept":
                has_accept = True
            if name == "content-type":
                has_content_type = True
        elif "=" in it:
            k, v = it.split("=", 1)
            if form:
                curl_item_opts.extend(["-F", it])
            else:
                data[k] = v
        else:
            raw_extras.append(it)
    return curl_item_opts + raw_extras, data, query, [], has_accept, has_content_type


def scan_user_headers(curl_opts: List[str]) -> Tuple[bool, bool]:
    has_accept = False
    has_content_type = False
    i = 0
    while i < len(curl_opts):
        a = curl_opts[i]
        val = None
        if a in ("-H", "--header") and i + 1 < len(curl_opts):
            val = curl_opts[i+1]
            i += 2
        elif a.startswith("-H") and len(a) > 2:
            val = a[2:]
            i += 1
        elif a.startswith("--header="):
            val = a.split("=", 1)[1]
            i += 1
        else:
            i += 1
        if val is not None:
            name = val.split(":", 1)[0].strip().lower()
            if name == "accept":
                has_accept = True
            if name == "content-type":
                has_content_type = True
    return has_accept, has_content_type


def make_urls(raw_url: str, query: List[Tuple[str, str]]) -> Tuple[str, str]:
    # URL used by curl.
    curl_url = raw_url
    if curl_url.startswith("//"):
        curl_url = curl_url[2:]
    elif curl_url.startswith(":"):
        curl_url = "localhost" + curl_url
        if curl_url.startswith("localhost:/"):
            curl_url = "localhost" + curl_url[len("localhost:"):]
    # Display/normalized URL printed on stderr.
    if raw_url.startswith("http://") or raw_url.startswith("https://"):
        display = raw_url
    elif raw_url.startswith("//"):
        display = "http:" + raw_url
    else:
        display = "http://" + raw_url
    if query:
        q = "&".join(urllib.parse.quote_plus(k) + "=" + urllib.parse.quote_plus(v) for k, v in query)
        sep_c = "&" if "?" in curl_url else "?"
        sep_d = "&" if "?" in display else "?"
        curl_url += sep_c + q
        display += sep_d + q
    return curl_url, display


def shell_quote_arg(s: str) -> str:
    if s == "":
        return '""'
    if re.search(r"[\s\"']", s):
        # Observed --curl output uses simple double quotes for arguments with spaces.
        return '"' + s.replace('"', '\\"') + '"'
    return s


def colorize_json_value(text: str) -> str:
    # Token-level highlighter for json.dumps(indent=4) output. It is intentionally
    # simple but follows the observed color palette closely.
    out = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c == '"':
            j = i + 1
            esc = False
            while j < n:
                ch = text[j]
                if esc:
                    esc = False
                elif ch == '\\':
                    esc = True
                elif ch == '"':
                    break
                j += 1
            tok = text[i:j+1]
            k = j + 1
            while k < n and text[k] in ' \t':
                k += 1
            if k < n and text[k] == ':':
                out.append('\033[34m' + tok + '\033[37m')
            else:
                out.append('\033[36m' + tok + '\033[37m')
            i = j + 1
        elif text.startswith("true", i) or text.startswith("null", i):
            word = "true" if text.startswith("true", i) else "null"
            out.append('\033[35m' + word + '\033[37m')
            i += len(word)
        elif text.startswith("false", i):
            out.append('\033[35mfalse\033[37m')
            i += 5
        elif c in '{}[]:,':
            out.append('\033[37m' + c)
            i += 1
        else:
            out.append(c)
            i += 1
    return ''.join(out) + '\n\033[0m'


def pretty_print_headers(header_bytes: bytes) -> None:
    txt = header_bytes.decode('iso-8859-1', 'replace')
    for line in txt.splitlines(True):
        stripped = line.rstrip('\r\n')
        ending = '\r' if line.endswith('\r\n') else ''
        if stripped == '':
            sys.stderr.write('\r\n')
            continue
        if stripped.startswith('HTTP/'):
            # HTTP/1.1 200 OK
            parts = stripped.split(' ', 2)
            if parts:
                proto = parts[0]
                rest = ' '.join(parts[1:])
                if '/' in proto:
                    a, b = proto.split('/', 1)
                    sys.stderr.write(f"\033[34m{a}\033[37m/\033[36m{b}")
                else:
                    sys.stderr.write(f"\033[34m{proto}")
                if rest:
                    if ' ' in rest:
                        code, reason = rest.split(' ', 1)
                        sys.stderr.write(f" {code}\033[33m {reason}{ending}\033[0m\n")
                    else:
                        sys.stderr.write(f" {rest}{ending}\033[0m\n")
            continue
        if ':' in stripped:
            name, val = stripped.split(':', 1)
            sys.stderr.write(f"\033[37m{name}:\033[36m{val}{ending}\033[0m\n")
        else:
            sys.stderr.write(stripped + ending + "\n")


def split_headers_body(blob: bytes) -> Tuple[bytes, bytes]:
    # Handle redirects/100-continue by using the last header block.
    marker = b"\r\n\r\n"
    if marker in blob:
        idx = blob.rfind(marker)
        # If multiple blocks, print all header blocks as curlie/curl verbose would.
        return blob[:idx+len(marker)], blob[idx+len(marker):]
    marker = b"\n\n"
    if marker in blob:
        idx = blob.rfind(marker)
        return blob[:idx+len(marker)], blob[idx+len(marker):]
    return b"", blob


def execute_pretty(curl_args: List[str]) -> int:
    # Dump response headers to stdout, then split and render them to stderr.
    args = [curl_path()] + curl_args + ["-D", "-"]
    # Remove verbose flags that were added for --pretty/default pretty, since we
    # reconstruct the pretty header stream ourselves.
    filtered = []
    skip = False
    for a in args:
        if a == "-v":
            continue
        filtered.append(a)
    try:
        p = subprocess.run(filtered, stdin=sys.stdin.buffer, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except FileNotFoundError:
        sys.stderr.write("curl: command not found\n")
        return 127
    headers, body = split_headers_body(p.stdout)
    if headers:
        pretty_print_headers(headers)
    if p.stderr:
        sys.stderr.buffer.write(p.stderr)
    # Pretty-print JSON bodies; otherwise write as-is.
    try:
        obj = json.loads(body.decode('utf-8'))
        text = json.dumps(obj, indent=4, ensure_ascii=False)
        sys.stdout.write(colorize_json_value(text))
    except Exception:
        sys.stdout.buffer.write(body)
    return p.returncode


def main(argv: List[str]) -> int:
    prog = sys.argv[0] if sys.argv else "curlie"
    if not argv:
        return print_curl_help(["--help", "all"], prog)
    if argv[0] in ("--version", "-V") and len(argv) == 1:
        rc, out, err = run_curl_for_text(["--version"])
        sys.stdout.write(out); sys.stderr.write(err); return rc
    if argv[0] in ("--manual", "-M") and len(argv) == 1:
        rc, out, err = run_curl_for_text(["--manual"])
        sys.stdout.write(out); sys.stderr.write(err); return rc
    if argv[0] in ("--help", "-h"):
        cat = argv[1] if len(argv) > 1 else "help"
        return print_curl_help(["--help", cat], prog)

    curl_mode, force_pretty, form, curl_opts, pos = split_args(argv)
    method, raw_url, items, extras = classify_positionals(pos)
    if not raw_url:
        return print_curl_help(["--help", "all"], prog)

    item_opts, data_obj, query, _unused, item_accept, item_ct = parse_items(items, form)
    curl_url, display_url = make_urls(raw_url, query)

    pretty = force_pretty or sys.stdout.isatty()
    stdin_data = not sys.stdin.isatty()

    user_accept, user_ct = scan_user_headers(curl_opts + item_opts)
    has_accept = item_accept or user_accept
    has_ct = item_ct or user_ct

    built: List[str] = []
    built.extend(curl_opts)
    if method:
        built.extend(["-X", method])
    # Item opts contain -H/-F pairs and raw extras. Keep them before data, as observed.
    built.extend(item_opts)
    has_json_body = bool(data_obj)
    if has_json_body:
        data_text = json.dumps(data_obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        built.extend(["-d", data_text])
    built.append(curl_url)
    built.extend(extras)
    built.extend(["-s", "-S"])
    if pretty:
        built.append("-v")
    if has_json_body:
        if not has_ct and not form:
            built.extend(["-H", "Content-Type: application/json"])
    elif stdin_data:
        built.extend(["-d@-"])
        if not has_ct:
            built.extend(["-H", "Content-Type: application/json"])
    if not has_accept:
        built.extend(["-H", "Accept: application/json, */*"])

    # The observed program prints the normalized URL on stderr before either
    # displaying the curl command or performing the request.
    sys.stderr.write(display_url + "\n")
    sys.stderr.flush()

    if curl_mode:
        sys.stdout.write("curl " + " ".join(shell_quote_arg(a) for a in built) + "\n")
        return 0

    if pretty:
        return execute_pretty(built)
    try:
        p = subprocess.run([curl_path()] + built, stdin=sys.stdin.buffer)
        return p.returncode
    except FileNotFoundError:
        sys.stderr.write("curl: command not found\n")
        return 127

if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
